const timestamp = Date.now().toString(16).padStart(8, '0').slice(-8);
const random1 = Math.floor(Math.random() * 0xFFFFFFFF).toString(16).padStart(8, '0');
const random2 = Math.floor(Math.random() * 0xFFFFFFFF).toString(16).padStart(8, '0');
const id_request = [timestamp, random1, random2].join('-');

let textoTranscripto;
try {
  textoTranscripto = $('Transcribe audio or video').first().json.text;
} catch (e) {
  textoTranscripto = undefined;
}


const question = $('Telegram Trigger').first().json.message.text
  || (textoTranscripto && textoTranscripto.length > 2000
      ? 'el cliente envio un audio y no se logro transcribir'
      : textoTranscripto);

let isVoice = false;

if ($('Telegram Trigger').first().json.message
    && $('Telegram Trigger').first().json.message.voice
    && $('Telegram Trigger').first().json.message.voice.file_id) {
  isVoice = true;
}

let bloqueRevision = '';
try {
  const veredicto = $('\'Worker: Judge AI\'').first().json;
  if (veredicto.estado_veredicto === 'CORREGIR') {
    bloqueRevision = `[REVISIÓN REQUERIDA] Tu respuesta anterior fue rechazada por el control de calidad. Motivo: ${veredicto.critica}. Corregí específicamente ese punto antes de responder de nuevo.`;
  }
} catch (e) {
  bloqueRevision = '';
}


const dic = {
  id_request,
  ID_SESSION: $('Telegram Trigger').first().json.message.chat.id,
  NAME: $('Telegram Trigger').first().json.message.from.first_name,
  QUESTION: question,
  IsVoice: isVoice,
  MESSAGE_COUNT: $input.first().json.MESSAGE_COUNT,
  SUMMARY: $input.first().json.SUMMARY,
  KEY_DATA: $input.first().json.KEY_DATA,
  LAST_UPDATED: $input.first().json.LAST_UPDATED,
  useContext: 'true',
  trys: 0,
  estado_veredicto: 'ACEPTADO',
  bloque_revision: bloqueRevision,
};

return [{ json: dic }];

