const raw = $input.first().json.output || $input.first().json.text || '';
console.log('RAW:', JSON.stringify(raw)); // esto te muestra los caracteres exactos, incluso los invisibles

const clean = raw.replace(/```json|```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(clean);
} catch (e) {
  console.log('ERROR PARSEANDO:', e.message);
  parsed = { AUDIO_TEXT: '' };
}

return [{ json: parsed }];

const original = $('Generate Variables').first().json;
const veredicto = $input.first().json; // esto es lo que devolvió el Juez

const item = {
  ...original,
  trys: veredicto.TRYS,
  estado_veredicto: veredicto.estado_veredicto,
  bloque_revision: veredicto.estado_veredicto === 'CORREGIR'
    ? `[REVISIÓN REQUERIDA] Tu respuesta anterior fue rechazada por el control de calidad. Motivo: ${veredicto.critica}. Corregí específicamente ese punto antes de responder de nuevo.`
    : ''
};

return [{ json: item }];

